// A reference is an editing recipe, not a source of footage or factual claims.
const bound=(n,a,b,d)=>Number.isFinite(Number(n))?Math.min(b,Math.max(a,Number(n))):d;
export function reviewClip(c={}){return {subtitle:String(c.subtitle||'').slice(0,150),titleStart:bound(c.titleStart,0,180,0),titleDuration:bound(c.titleDuration,.3,180,180),titleScale:bound(c.titleScale,3,10,6),titleY:bound(c.titleY,15,80,58),motion:['none','push','pull'].includes(c.motion)?c.motion:'none',cropX:bound(c.cropX,0,1,.5),cropY:bound(c.cropY,0,1,.5)}}
export function buildReview({assets,chapters,title,subtitle='',aspect='9:16',music=null,originalAudio=true}){
 if(!String(title||'').trim())throw Error('Введите заголовок ролика и обложки.');
 if(!Array.isArray(chapters)||!chapters.length||chapters.length>60)throw Error('Добавьте от 1 до 60 фрагментов.');
 let duration=0;const clips=chapters.map((c,i)=>{const a=assets.find(a=>a.id===c.assetId);if(!a||a.type==='audio')throw Error(`Фрагмент ${i+1}: выберите видео или фото.`);const start=Number(c.start),end=Number(c.end),limit=a.type==='image'?60:Number(a.duration);if(!Number.isFinite(start)||!Number.isFinite(end)||start<0||end<=start||end>limit+.001)throw Error(`Фрагмент ${i+1}: время должно быть в пределах исходника.`);const speed=[.5,1,1.5,2].includes(Number(c.speed))?Number(c.speed):1;duration+=(end-start)/speed;return {assetId:a.id,start,end,speed,transition:i&&c.transition==='fade'?'fade':'cut',title:String(c.title||'').slice(0,100),textStyle:'review',textPosition:'center',...reviewClip(c)}});
 if(duration>180)throw Error('Сократите обзор до 180 секунд.');
 if(music&&!assets.some(a=>a.id===music&&a.type==='audio'))throw Error('Музыка отсутствует в библиотеке.');
 return {clips,preset:'dynamic',aspect:['9:16','16:9','1:1'].includes(aspect)?aspect:'9:16',targetDuration:duration,captionsEnabled:false,cues:[],originalAudio:!!originalAudio,music,musicVolume:.15,cover:{style:'automotive',title:String(title).trim().slice(0,100),subtitle:String(subtitle).slice(0,150),frame:Math.min(.8,duration/2),logo:true,shade:.4},brief:'Обзор: ведущий, короткие названия, пояснение второй строкой, чистые склейки.'};
}
export function seedChapters(assets){return assets.filter(a=>a.type!=='audio'&&!a.builtin).slice(0,8).map(a=>({assetId:a.id,start:0,end:Math.min(a.type==='image'?4:Number(a.duration),6),title:a.name.replace(/\.[^.]+$/,'').replace(/[_-]+/g,' ').slice(0,60),subtitle:'',motion:'none'}))}
export function drawReviewTitle(ctx,canvas,clip,offset){if(!clip.title)return;const s=reviewClip(clip);if(offset<s.titleStart||offset>=s.titleStart+s.titleDuration)return;const w=canvas.width,h=canvas.height,short=Math.min(w,h),progress=Math.min(1,(offset-s.titleStart)/.18),ease=1-(1-progress)**3;let fs=short*s.titleScale/100;ctx.save();ctx.textAlign='center';ctx.textBaseline='top';ctx.globalAlpha=ease;ctx.font=`700 ${fs}px "Golos Text", sans-serif`;while(ctx.measureText(clip.title).width>w*.84&&fs>short*.025){fs-=1;ctx.font=`700 ${fs}px "Golos Text", sans-serif`}const y=h*s.titleY/100+(1-ease)*short*.018;ctx.shadowColor='rgba(0,0,0,.9)';ctx.shadowBlur=short*.012;ctx.shadowOffsetY=short*.003;ctx.fillStyle='#fff';ctx.fillText(clip.title,w/2,y);if(s.subtitle){const size=fs*.43;ctx.font=`600 ${size}px "Golos Text", sans-serif`;ctx.fillText(s.subtitle.toLocaleUpperCase('ru'),w/2,y+fs*1.12,w*.84)}ctx.restore()}
